import React from "react";
import FileUpload from "./components/FileUpload";
import FileList from "./components/FileList";
import Login from "./components/Login"; // ✅ Add Login component
import { ToastContainer } from "react-toastify";
import "react-toastify/dist/ReactToastify.css";
import "./App.css";

function App() {
  const token = localStorage.getItem("token"); // ✅ Check if logged in

  return (
    <div className="App">
      {/* ===== Navbar ===== */}
      <nav className="navbar">
        <div className="nav-logo">Sculpx File Manager</div>
        <ul className="nav-links">
          <li><a href="#upload">Upload</a></li>
          <li><a href="#files">Files</a></li>
          <li><a href="https://www.mongodb.com/" target="_blank" rel="noreferrer">MongoDB</a></li>
          {token && (
            <li>
              <button
                onClick={() => {
                  localStorage.removeItem("token");
                  window.location.reload();
                }}
                style={{
                  background: "#ff4d4d",
                  color: "white",
                  border: "none",
                  padding: "6px 12px",
                  borderRadius: "6px",
                  cursor: "pointer",
                  fontWeight: "500",
                }}
              >
                Logout
              </button>
            </li>
          )}
        </ul>
      </nav>

      {/* ===== Main Content ===== */}
      <main className="main-content">
        {!token ? (
          <>
            <h1 className="page-title">🔐 Please Login to Continue</h1>
            <Login />
          </>
        ) : (
          <>
            <h1 className="page-title">📂 Scalable File Management System</h1>

            <section id="upload">
              <FileUpload />
            </section>

            <section id="files">
              <FileList />
            </section>
          </>
        )}
      </main>

      <ToastContainer position="top-right" autoClose={3000} />
    </div>
  );
}

export default App;
